<template><view class="page"><MeetingContentHeader :title="detail.title||'会议通知'" :activity-id="activityId"/><view v-if="loading" class="state">加载中...</view><view v-else-if="detail.noticeId" class="detail"><view class="priority">{{ priority(detail.priority) }}</view><rich-text :nodes="detail.contentHtml"/></view><view v-else class="list"><view v-for="item in rows" :key="item.noticeId" class="card" @click="open(item)"><view class="title">{{ item.title }}</view><view class="sub">{{ priority(item.priority) }} · {{ item.publishTime }}</view></view><view v-if="!rows.length" class="state">暂无通知</view></view></view></template>
<script setup>import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import MeetingContentHeader from'@/components/MeetingContentHeader.vue';import{getNotice,getNotices}from'@/api/portal/notice';const activityId=ref(''),rows=ref([]),detail=ref({}),loading=ref(true);const priority=v=>({normal:'普通',important:'重要',urgent:'紧急'})[v]||'普通';onLoad(o=>{activityId.value=o?.activityId||'';if(o?.noticeId){getNotice(activityId.value,o.noticeId).then(r=>detail.value=r.data||{}).finally(()=>loading.value=false)}else getNotices(activityId.value).then(r=>rows.value=r.data?.notices||[]).finally(()=>loading.value=false)});function open(item){uni.navigateTo({url:`/pages/meeting/notice?activityId=${activityId.value}&noticeId=${item.noticeId}`})}</script><style scoped>.page{min-height:100vh;background:#f5f7fa}.list,.detail{padding:110rpx 24rpx 24rpx}.card,.detail{padding:24rpx;margin-bottom:18rpx;background:#fff;border-radius:16rpx}.title{font-weight:600}.sub,.priority{margin:10rpx 0;color:#909399;font-size:24rpx}.priority{color:#e6a23c}.state{padding:180rpx 24rpx;text-align:center;color:#909399}</style>
